const body = $json.body ?? $json;
const baseQuestion = body.question ?? body.text ?? body.previousQuestion;
const clarification = body.clarificationAnswer;
const question = clarification && typeof baseQuestion === 'string' ? `${baseQuestion}\n사용자 추가 답변: ${clarification}` : baseQuestion;
if (typeof question !== 'string' || !question.trim()) {
  return [{ json: { route: 'error', response: { status: 'error', error: { code: 'INPUT_INVALID', message: 'question is required', next_action: 'repair_input' } } } }];
}
const query = {
  schema_version: '1.0',
  text: question.trim(),
  subject: body.subject ?? null,
  context: body.context ?? {},
  ambiguities: Array.isArray(body.ambiguities) ? body.ambiguities : [],
  confidence: typeof body.confidence === 'number' ? body.confidence : null,
  requires: Array.isArray(body.requires) ? body.requires : []
};
return [{ json: {
  sessionId: body.sessionId ?? `n8n-${Date.now()}`,
  snapshot: body.snapshot ?? null,
  query,
  plannerAttempt: 1,
  repairFeedback: null
} }];

const item = $input.first().json;
const system = 'You are the PoE PoB Agent planner. Return JSON only with schema_version, intent, operation, evidenceLevel, required_evidence, stop_condition, and steps. Use only canonical Tool names. For mechanism, damage, and compare questions, include detailed evidence tools. If the subject is ambiguous, return stop_condition.type=ask_user and a clarification object. Never invent values.';
const user = { query: item.query, snapshot: item.snapshot, repair_feedback: item.repairFeedback };
return [{ json: { ...item, plannerRequest: { model: $env.POB_AGENT_MODEL ?? 'qwen3:8b', temperature: 0, messages: [{ role: 'system', content: system }, { role: 'user', content: JSON.stringify(user) }] } } }];

const response = $input.first().json;
let base;
try { base = $('Build Repair Request').item.json; } catch (error) { base = $('Build Planner Request').item.json; }
const raw = response.choices?.[0]?.message?.content ?? response.message?.content ?? response.content ?? response;
let plan;
try { plan = typeof raw === 'string' ? JSON.parse(raw.replace(/^```json\s*|\s*```$/g, '')) : raw; } catch (error) { plan = null; }
return [{ json: { ...base, plan, plannerRaw: typeof raw === 'string' ? raw.slice(0, 2000) : null } }];

const item = $input.first().json;
const plan = item.plan;
const attempt = item.plannerAttempt ?? 1;
const allowed = new Set(['get_highest_dps_skill','resolve_skill_context','get_skill_dps','get_skill_breakdown','get_damage_breakdown','explain_stat','get_projectile_count','get_skill_chain','get_duration','get_curse_limit','get_elemental_penetration','get_socket_order','search_knowledge','compare_build_states']);
const required = {
  mechanism: { tools: ['resolve_skill_context','get_skill_breakdown'], evidence: ['calculated','knowledge'] },
  damage: { tools: ['get_skill_dps','get_damage_breakdown'], evidence: ['calculated','authoritative'] },
  compare: { tools: ['compare_build_states'], evidence: ['calculated'] },
  build_comparison: { tools: ['compare_build_states'], evidence: ['calculated'] }
};
const fail = (code, message, details = {}) => ({ ...item, route: attempt < 5 ? 'planner_retry' : 'error', plannerAttempt: attempt + 1, repairFeedback: { code, message, details, instruction: 'Return a corrected JSON plan using canonical Tool names and all required evidence.' }, response: { status: 'error', error: { code: attempt < 5 ? code : 'REPAIR_INPUT', message, details, attempt, max_attempts: 5, next_action: attempt < 5 ? 'retry_planner' : 'human_review' } } });
if (!plan || typeof plan !== 'object' || !Array.isArray(plan.steps)) return [{ json: fail('OUTPUT_CONTRACT', 'planner did not return a valid JSON plan') }];
if (plan.stop_condition?.type === 'ask_user' || plan.intent === 'unknown' || (Array.isArray(plan.ambiguities) && plan.ambiguities.length)) {
  const clarification = plan.clarification ?? { question: '어떤 스킬 또는 빌드를 기준으로 분석할까요?', options: ['현재 Main Skill', '가장 높은 DPS 스킬', '스킬명을 직접 입력'] };
  return [{ json: { ...item, route: 'ask_user', response: { status: 'needs_user_input', clarification } } }];
}
const names = plan.steps.map(step => step?.tool);
const bad = names.find(name => !allowed.has(name));
if (bad) return [{ json: fail('UNKNOWN_TOOL', 'planner selected a non-canonical Tool', { tool: bad }) }];
const req = required[plan.intent];
if (req) {
  const missingTools = req.tools.filter(tool => !names.includes(tool));
  const declared = new Set(Array.isArray(plan.required_evidence) ? plan.required_evidence : []);
  const missingEvidence = req.evidence.filter(value => !declared.has(value));
  if (missingTools.length || missingEvidence.length) return [{ json: fail('PLAN_INCOMPLETE', 'plan lacks required Tool or evidence', { missingTools, missingEvidence }) }];
}
return [{ json: { ...item, route: 'execute', plan } }];

const item = $input.first().json;
const system = 'Repair the previous PoB Tool plan. Return JSON only. Preserve the query, use canonical Tool names, and satisfy the required evidence list.';
return [{ json: { ...item, plannerRequest: { model: $env.POB_AGENT_MODEL ?? 'qwen3:8b', temperature: 0, messages: [{ role: 'system', content: system }, { role: 'user', content: JSON.stringify({ query: item.query, snapshot: item.snapshot, repair_feedback: item.repairFeedback }) }] } } }];

const response = $input.first().json;
const base = $('Validate Plan Completeness').item.json;
const result = response.execution ?? response.result ?? response;
const steps = Array.isArray(result.steps) ? result.steps : [];
const bad = steps.find(step => step.status !== 'ok');
const incomplete = steps.some(step => step.uncertainty?.reason === 'missing_evidence_graph');
if (bad || incomplete) return [{ json: { ...base, ...response, route: 'partial', response: { status: 'partial', answer: 'PoB 근거가 부족해 추측하지 않습니다.', execution: result, uncertainty: bad?.error ?? { code: 'EVIDENCE_INCOMPLETE' } } } }];
return [{ json: { ...base, ...response, route: 'final', finalRequest: { model: $env.POB_AGENT_MODEL ?? 'qwen3:8b', temperature: 0, messages: [{ role: 'system', content: 'Answer in Korean using only the supplied PoB Tool results. Separate final values, applied effects, source trace, and Evidence Graph. Never guess.' }, { role: 'user', content: JSON.stringify({ query: base.query, results: result }) }] } } }];

const response = $input.first().json;
const base = $('Evidence Gate').item.json;
const answer = response.choices?.[0]?.message?.content ?? response.message?.content ?? response.content ?? response;
return [{ json: { status: 'ok', answer, query: base.query, plan: base.plan } }];
